# M9 投手版验收（HTTP 层）。测试账号 acc_buyer（pc_staff），测试订单取沙盒里最新一张。
. /var/tmp/m1-accept/lib.sh
O=$($WA eval 'echo wc_get_orders( array( "limit" => 1, "return" => "ids" ) )[0];' 2>/dev/null | tail -1)
$WA user get acc_buyer --field=ID >/dev/null 2>&1 || $WA user create acc_buyer acc_buyer@example.test --role=pc_staff --porcelain >/dev/null 2>&1
$WA peptide buyer on acc_buyer 2>&1 | tail -1; login acc_buyer $O
H=$(curl -s -o /dev/null -w '%{redirect_url}' -H "Cookie: $COOKIE" "$ADMIN/wp-admin/"); echo "首页 → $H $(code "$H")"
echo "## 菜单"; menu "$H"
get "$H" > /tmp/acc-home.html; echo "## 命令面板：menu_commands 出现 $(grep -c 'menu_commands' /tmp/acc-home.html) 次；源码里出现禁用菜单名：客户 $(grep -c 'wc-admin&#038;path=/customers\|path=%2Fcustomers' /tmp/acc-home.html) pc-mail $(grep -c 'page=pc-mail' /tmp/acc-home.html) pc-system $(grep -c 'page=pc-system' /tmp/acc-home.html) pc-promotions $(grep -c 'page=pc-promotions' /tmp/acc-home.html) wc-settings $(grep -c 'page=wc-settings' /tmp/acc-home.html)"; rm -f /tmp/acc-home.html
echo "## 允许的页面"; for p in "admin.php?page=wc-orders&status=wc-processing" "admin.php?page=pc-recovery" "admin.php?page=pc-data" "admin.php?page=pc-visitors" "admin.php?page=pc-buyer-ads" "admin.php?page=pc-store-info"; do echo "$(code "$ADMIN/wp-admin/$p") $p"; done
echo "## 订单"; echo "原生订单页 → $(where "$ADMIN/wp-admin/admin.php?page=wc-orders&action=edit&id=$O")"; echo "pc-order 详情 $(code "$ADMIN/wp-admin/admin.php?page=pc-order&id=$O")"; echo "pc_native $(code "$ADMIN/wp-admin/admin.php?page=wc-orders&action=edit&id=$O&pc_native=1")"
get "$ADMIN/wp-admin/admin.php?page=pc-order&id=$O" > /tmp/acc-o.html; echo "详情页 $(wc -c < /tmp/acc-o.html) 字节；致命错误 $(grep -ciE 'fatal error|critical error' /tmp/acc-o.html)；写控件：save_order $(grep -c 'save_order' /tmp/acc-o.html) refund $(grep -ciE 'refund-items|do-manual-refund' /tmp/acc-o.html) order_status 下拉 $(grep -c 'name="order_status"' /tmp/acc-o.html) 表单 POST $(grep -ciE '<form[^>]+method="post"' /tmp/acc-o.html) 按钮 $(grep -oE '<button[^>]*>[^<]{0,30}' /tmp/acc-o.html | sed -E 's/<[^>]+>//' | sort -u | tr '\n' '/' | cut -c1-200)"; rm -f /tmp/acc-o.html
echo "导出 $(curl -s -o /dev/null -w '%{http_code} %{content_type} %{size_download}' -H "Cookie: $COOKIE" "$ADMIN/wp-admin/admin-post.php?action=pc_buyer_orders_export")"
echo "## 必须 403"; bad=0; for p in "admin.php?page=pc-promotions" "admin.php?page=pc-system" "admin.php?page=pc-staff" "admin.php?page=wc-settings" plugins.php users.php "edit.php?post_type=product" "admin.php?page=pc-manual-order" "post-new.php?post_type=product" "admin.php?page=pc-store-design" "admin.php?page=pc-mail" "admin.php?page=pc-shipping" "admin.php?page=pc-apps" options-general.php "admin.php?page=wc-admin&path=/customers" "edit.php?post_type=shop_coupon" themes.php tools.php export.php "admin.php?page=wc-status" "admin.php?page=pc-media" upload.php "admin.php?page=pc-accounts" "admin.php?page=pc-ship-preview" "admin.php?page=pc-track-ball" "admin.php?page=pc-stock-range"; do c=$(code "$ADMIN/wp-admin/$p"); [ "$c" = 403 ] || { bad=$((bad+1)); echo "  不是 403：$c $p"; }; done; echo "26 个地址，非 403 的 $bad 个"
echo "## REST（带有效 nonce）"; for r in /wc/v3/orders /wc/v3/payment_gateways /wc/v3/customers /wc/v3/settings /wc/v3/products /wc/v3/coupons /wc-analytics/customers "/wp/v2/users&context=edit"; do echo -n "$(code -H "X-WP-Nonce: $NONCE_wp_rest" "$ADMIN/?rest_route=$r") "; done; echo
echo "## 订单写操作重放（带有效 nonce）"
echo -n "ajax 改状态 $(code "$ADMIN/wp-admin/admin-ajax.php?action=woocommerce_mark_order_status&status=completed&order_id=$O&_wpnonce=$NONCE_woocommerce_mark_order_status")；"
echo -n "ajax 退款 $(code -X POST -d "action=woocommerce_refund_line_items&order_id=$O&refund_amount=1&security=$NONCE_order_item" "$ADMIN/wp-admin/admin-ajax.php")；"
echo -n "ajax 备注 $(code -X POST -d "action=woocommerce_add_order_note&post_id=$O&note=x&note_type=&security=$NONCE_order_item" "$ADMIN/wp-admin/admin-ajax.php")；"
echo -n "保存 $(code -X POST -d "action=edit_order&id=$O&order_status=wc-completed&_wpnonce=$(eval echo \$NONCE_update_order_$O)&save=Update" "$ADMIN/wp-admin/admin.php?page=wc-orders&action=edit&id=$O")；"
echo -n "批量回收 $(code "$ADMIN/wp-admin/admin.php?page=wc-orders&action=trash&id[]=$O&_wpnonce=$NONCE_bulk_orders")；delete_all $(code "$ADMIN/wp-admin/admin.php?page=wc-orders&delete_all=1&status=trash&_wpnonce=$NONCE_bulk_orders")；"
echo "REST 改 $(code -H "X-WP-Nonce: $NONCE_wp_rest" -H 'Content-Type: application/json' -X POST -d '{"status":"completed"}' "$ADMIN/?rest_route=/wc/v3/orders/$O")；REST 删 $(code -H "X-WP-Nonce: $NONCE_wp_rest" -H 'X-HTTP-Method-Override: DELETE' -X POST "$ADMIN/?rest_route=/wc/v3/orders/$O")"
echo "pc-order 上的 POST：$(code -X POST -d "id=$O&status=completed&note=x&action=save" "$ADMIN/wp-admin/admin.php?page=pc-order&id=$O")；admin-post pc_order_save $(code -X POST -d "action=pc_order_save&id=$O" "$ADMIN/wp-admin/admin-post.php")"
echo "订单 $O 现状：$($WA eval "\$o = wc_get_order( $O ); echo \$o->get_status(), ' 备注 ', count( wc_get_order_notes( array( 'order_id' => $O ) ) ), ' 退款 ', count( \$o->get_refunds() );" 2>/dev/null | tail -1)"
echo "## 强制改密码"; $WA peptide buyer on acc_buyer --must-change-password >/dev/null 2>&1; login acc_buyer $O; for p in "" "admin.php?page=pc-data" "admin.php?page=pc-order&id=$O"; do echo "'$p' → $(where "$ADMIN/wp-admin/$p")"; done
echo "## 改回"; $WA peptide buyer off acc_buyer 2>&1 | tail -1; $WA peptide buyer list 2>&1 | sed -n 2p
login sandbox_admin; echo "管理员：员工页“后台版本”$(get "$ADMIN/wp-admin/admin.php?page=pc-staff" | grep -c '后台版本') 处；管理员首页 menu_commands $(get "$ADMIN/wp-admin/admin.php?page=pc-overview" | grep -c menu_commands)"
